    }

    /* Bottom bar */
    .bottom-bar {
      background: var(--panel-bg);
      border-top: 1px solid var(--border);
      padding: 8px 16px;
      display: flex;
      gap: 16px;
      align-items: center;
      font-size: 11px;
      color: var(--text-dim);
      flex-shrink: 0;
    }
    .bottom-bar .refresh {
      color: var(--accent);
      cursor: pointer;
    }
    .bottom-bar .refresh:hover { text-decoration: underline; }

    /* Tab buttons */
    .tab-row {
      display: flex;
      gap: 4px;
      margin-bottom: 8px;
    }
    .tab-btn {
      font-size: 11px;
      padding: 4px 10px;
      border: 1px solid var(--border);
      border-radius: 3px;
      background: transparent;
      color: var(--text-dim);
      cursor: pointer;
      transition: all 0.2s;
    }
    .tab-btn:hover { border-color: var(--accent); color: var(--text); }
    .tab-btn.active { background: var(--accent); color: #fff; border-color: var(--accent); }

    /* SVG topology */
    .topo-node { fill: var(--accent); }
    .topo-node.agent { fill: #3fb950; }
    .topo-node.discussion { fill: #58a6ff; }
    .topo-node.task { fill: #d29922; }
    .topo-node.tool { fill: #a371f7; }
    .topo-link { stroke: var(--border); stroke-width: 1; }
    .topo-label { fill: var(--text-dim); font-size: 9px; }

    /* Responsive */
    @media (max-width: 900px) {
      .main-grid {
        grid-template-columns: 1fr;
        grid-template-rows: auto;
      }
    }
  </style>
